# Проверка перед включением человекопонятных адресов (ЧПУ). Только читает.
# Вставляется одной строкой в Shell хостинга (ispmanager -> «Shell-клиент»).
# Показывает правила .htaccess, настройки ЧПУ в базе, сколько включённых
# товаров/разделов/страниц уже имеют адрес, повторы и кириллицу в адресах,
# адреса служебных страниц и открывает раздел и товар по новому адресу.
# Прогнана на stroigeroi.ru 23.09.2026, результат — в README, «Человекопонятные адреса».
( cd /var/www/u2934771/data/www/stroigeroi.ru || exit 1; echo "-- .htaccess"; grep -nE "^[[:space:]]*Rewrite|_route_" .htaccess | head -12; R=$(php -r 'mysqli_report(MYSQLI_REPORT_OFF); include "config.php"; $m = @new mysqli(DB_HOSTNAME, DB_USERNAME, DB_PASSWORD, DB_DATABASE, (int)DB_PORT); if ($m->connect_error) { echo "DB: ", $m->connect_error, "\n"; exit(1); } $m->set_charset("utf8"); $q = function ($s) use ($m) { $r = $m->query(str_replace("{p}", DB_PREFIX, $s)); if (!$r) { echo "SQL: ", $m->error, "\n"; return array(); } $a = array(); while ($x = $r->fetch_row()) $a[] = $x; return $a; }; echo "-- settings\n"; foreach ($q("SELECT `key`, LEFT(`value`, 50) FROM {p}setting WHERE store_id = 0 AND (`key` LIKE \"config_seo%\" OR `key` LIKE \"%seopro%\" OR `key` LIKE \"%seo_pro%\") ORDER BY `key`") as $r) echo $r[0], " = ", $r[1], "\n"; echo "-- enabled / with address\n"; foreach (array("product" => "t.status = 1", "category" => "t.status = 1", "information" => "t.status = 1", "manufacturer" => "1") as $t => $w) { $r = $q("SELECT COUNT(*), IFNULL(SUM(EXISTS(SELECT 1 FROM {p}seo_url s WHERE s.store_id = 0 AND s.keyword <> \"\" AND s.query = CONCAT(\"{$t}_id=\", t.{$t}_id))), 0) FROM {p}{$t} t WHERE $w"); echo $t, ": ", ($r ? $r[0][0] . " / " . $r[0][1] : "?"), "\n"; } $d = $q("SELECT keyword, GROUP_CONCAT(query SEPARATOR \" \") FROM {p}seo_url WHERE store_id = 0 AND keyword <> \"\" GROUP BY language_id, keyword HAVING COUNT(*) > 1"); echo "-- same address twice: ", count($d), "\n"; foreach (array_slice($d, 0, 5) as $r) echo "   ", $r[0], ": ", $r[1], "\n"; $c = $q("SELECT COUNT(*) FROM {p}seo_url WHERE store_id = 0 AND (LENGTH(keyword) <> CHAR_LENGTH(keyword) OR keyword LIKE \"% %\")"); echo "-- non-latin addresses: ", ($c ? $c[0][0] : "?"), "\n"; echo "-- addresses of routes\n"; foreach ($q("SELECT query, keyword FROM {p}seo_url WHERE store_id = 0 AND query NOT LIKE \"%id=%\" ORDER BY query LIMIT 15") as $r) echo "   ", $r[0], " -> ", $r[1], "\n"; $a = $q("SELECT s.keyword FROM {p}seo_url s JOIN {p}category t ON s.query = CONCAT(\"category_id=\", t.category_id) WHERE t.status = 1 AND s.store_id = 0 AND s.keyword <> \"\" ORDER BY t.category_id DESC LIMIT 1"); $b = $q("SELECT s.keyword FROM {p}seo_url s JOIN {p}product t ON s.query = CONCAT(\"product_id=\", t.product_id) WHERE t.status = 1 AND s.store_id = 0 AND s.keyword <> \"\" ORDER BY t.product_id DESC LIMIT 1"); echo "SAMPLES", ($a ? " " . $a[0][0] : ""), ($b ? " " . $b[0][0] : ""), "\n";'); echo "$R" | grep -v "^SAMPLES"; for u in $(echo "$R" | sed -n "s/^SAMPLES//p") proverka-chpu-404; do echo "== /$u"; curl -s -w '\nHTTP %{http_code} %{redirect_url}\n' "https://stroigeroi.ru/$u" | grep -oE '<title>[^<]*|^HTTP [0-9]+.*'; done )
